                new GfxMapLights.Fixture { Layer = "accent", Note = "Exit arch, the way out to CR06, framed by the two inner lanterns: a focal spot from 1.1 m above the centre block, covering the arch and the floor at its foot where the route turns. Arch at y 3: d 10.7, cos 0.61, W 0.55 -> E 0.85; 1.5-2.5 with the court sky", Type = LightType.Spot, At = new Vector3(0f, 11.5f, 29.5f), Aim = new Vector3(0f, -8.5f, 6.5f), Angle = 60f, Inner = 40f, Intensity = 250f, Range = 15f, Color = new Color(1f, 0.98f, 0.95f) },
                new GfxMapLights.Fixture { Layer = "accent", Note = "Inside each gate tunnel, past the door: daylight spilling in from the court, so the passage under the gate (dark StoneShadow linings) is not a dark mouth. Linings 1.7-2.3 m away get E 0.7-1; the floor gets 0.3 plus the gate spot and the court sky", Type = LightType.Point, At = new Vector3(-12f, 4f, 28.8f), To = new Vector3(12f, 4f, 28.8f), Count = 2, Intensity = 5f, Range = 8f, Color = new Color(1f, 0.98f, 0.95f) },
            },
            ["MG_J_PalaceLaundry"] = new List<GfxMapLights.Fixture>
            {
                new GfxMapLights.Fixture { Layer = "daylight", Note = "West arcade windows' sky light. One shadowless spot just inside each of the three pool bays' lower openings: 2.2 m in front of the swaying sheets, 0.6 m above the line, under the balcony. Aimed inward and down so the water and tubs in front of each window are a little brighter than the pool's middle, and the room reads as lit from its windows. Sits between the lanterns on the piers. E about 0.45 on the tubs 5 m in front (cos 0.88, W(0.5) 0.88): I = 0.45*25/(0.88*0.88) = 14.", Type = LightType.Spot, At = new Vector3(-19f, 4.8f, 7.5f), To = new Vector3(-19f, 4.8f, 17.5f), Count = 3, Aim = new Vector3(1f, -0.6f, 0f), Angle = 120f, Inner = 80f, Intensity = 14f, Range = 10f, Color = new Color(0.98f, 0.99f, 1f) },
                new GfxMapLights.Fixture { Layer = "daylight", Note = "East arcade windows' sky light, the mirror of the west row, on the sunny side where it joins the sun's stripes. Same sizing: E about 0.45 at 5 m gives I 14.", Type = LightType.Spot, At = new Vector3(19f, 4.8f, 7.5f), To = new Vector3(19f, 4.8f, 17.5f), Count = 3, Aim = new Vector3(-1f, -0.6f, 0f), Angle = 120f, Inner = 80f, Intensity = 14f, Range = 10f, Color = new Color(0.98f, 0.99f, 1f) },
                new GfxMapLights.Fixture { Layer = "general", Note = "Chandelier room light, the west and east chandeliers of the first row (x ±12, z 7.5). Each chandelier owns the down-light on its pool. A 150-degree spot 1.5 m under the ring (about 0.9 m clear), tilted 19 degrees toward the entry so the station, entry band and entry wall share it. Near-daylight so the white tile does not yellow; the warmth stays in the candles. E about 0.5 on the tubs 8.8 m below (cos 0.94, W(0.49) 0.89, lum 0.96): I = 0.5*77/(0.94*0.89*0.96) = 48, set to 46.", Type = LightType.Spot, At = new Vector3(-12f, 9.2f, 7.5f), To = new Vector3(12f, 9.2f, 7.5f), Count = 2, Aim = new Vector3(0f, -1f, -0.35f), Angle = 150f, Inner = 100f, Intensity = 46f, Range = 18f, Color = new Color(1f, 0.96f, 0.9f) },
                new GfxMapLights.Fixture { Layer = "general", Note = "Chandelier room light, the west and east chandeliers of the last row (x ±12, z 17.5). Tilted 19 degrees toward the back wall so the gate approach and the gate strip are lifted before the gate accent. Same sizing as the first row: I 46.", Type = LightType.Spot, At = new Vector3(-12f, 9.2f, 17.5f), To = new Vector3(12f, 9.2f, 17.5f), Count = 2, Aim = new Vector3(0f, -1f, 0.35f), Angle = 150f, Inner = 100f, Intensity = 46f, Range = 18f, Color = new Color(1f, 0.96f, 0.9f) },
                new GfxMapLights.Fixture { Layer = "general", Note = "Chandelier room light, the three aisle chandeliers (x 0, z 7.5/12.5/17.5), straight down. Kept lower than the side rows so the central aisle, which is not the race line, does not outshine the pools. They also light the inner halves of both pools. E about 0.35 on the aisle 9.2 m below (W(0.51) 0.87): I = 0.35*85/(0.87*0.96) = 36, set to 32.", Type = LightType.Spot, At = new Vector3(0f, 9.2f, 7.5f), To = new Vector3(0f, 9.2f, 17.5f), Count = 3, Aim = new Vector3(0f, -1f, 0f), Angle = 150f, Inner = 100f, Intensity = 32f, Range = 18f, Color = new Color(1f, 0.96f, 0.9f) },
                new GfxMapLights.Fixture { Layer = "wash", Note = "West wall wash: the room's daylight spreading over a pale wall (hidden, neutral). Three spots 10 m out over the pool at balcony height, aimed at mid-wall. The 70-degree inner cone covers wainscot, sheets, lantern piers, balcony, upper-window piers and cornice (y 0-13) and about 12 m of wall each, so there are no scallops and no dark upper half. E about 0.55 per spot at 10.1 m (cos 0.99, W(0.56) 0.81): I = 0.55*102/(0.99*0.81*0.97) = 72, set to 70. Neighbours overlap to about 0.9 direct.", Type = LightType.Spot, At = new Vector3(-12f, 8f, 4.5f), To = new Vector3(-12f, 8f, 19.5f), Count = 3, Aim = new Vector3(-10f, -1.5f, 0f), Angle = 100f, Inner = 70f, Intensity = 70f, Range = 18f, Color = new Color(1f, 0.97f, 0.94f) },
                new GfxMapLights.Fixture { Layer = "wash", Note = "East wall wash, the mirror of the west. This wall faces away from the sun, so without it the arcade would sit dark against its bright windows. Same sizing: I 70.", Type = LightType.Spot, At = new Vector3(12f, 8f, 4.5f), To = new Vector3(12f, 8f, 19.5f), Count = 3, Aim = new Vector3(10f, -1.5f, 0f), Angle = 100f, Inner = 80f, Intensity = 70f, Range = 18f, Color = new Color(1f, 0.97f, 0.94f) },
                new GfxMapLights.Fixture { Layer = "wash", Note = "Back wall between the gates, the far end of the axis seen from the entrance. One wide spot from mid-hall, moved 2.6 m off the centre chandelier, aimed at the wall's lower half (x about ±9). E about 0.4 at (0,4,23.3), d 10.1, cos 0.87, W 0.81: I = 0.4*102/(0.87*0.81*0.97) = 60, set to 55.", Type = LightType.Spot, At = new Vector3(0f, 9f, 14.5f), Aim = new Vector3(0f, -5f, 8.8f), Angle = 120f, Inner = 80f, Intensity = 55f, Range = 18f, Color = new Color(1f, 0.97f, 0.94f) },
                new GfxMapLights.Fixture { Layer = "accent", Note = "The hero, each team's gate: the arch frame, banner, progress bar and the J_Leaf door 3 m inside. One shadow-casting spot per gate, from high on the approach side 9 m out, at (±12, 8, 15) = arch top + offset. Aimed down through the arch at the door's foot. The ray to the door's top passes the 7.2 m arch at y 6.0, so the whole door is lit, and the closed door stops the beam. Pieces coming in cast contact shadows into the gate. E +1.4 on the arch at 9.4 m (cos 0.88, W(0.43) 0.93): I = 1.4*88/(0.88*0.93*0.98) = 154, set to 155. The door gets +0.6.", Type = LightType.Spot, Each = "arch", Anchor = "top", Offset = new Vector3(0f, 0.8f, -8.8f), Max = 2, Aim = new Vector3(0f, -7f, 12f), Angle = 46f, Inner = 26f, Intensity = 155f, Range = 22f, Color = new Color(1f, 0.98f, 0.95f), Shadows = true },
                new GfxMapLights.Fixture { Layer = "general", Note = "Entry band and station. The first bay has no chandelier, and this is the start view. Two wide spots above the entry band, tilted toward the hall so that the entry corridor behind the entry wall gets under 0.01. They also lift the entry wall's lower part and the game signs' faces to about 0.3. E about 0.35 on the floor 8.5 m below (W(0.65) 0.67): I = 0.35*72/(0.67*0.97) = 39, set to 38.", Type = LightType.Spot, At = new Vector3(-9f, 8.5f, 2f), To = new Vector3(9f, 8.5f, 2f), Count = 2, Aim = new Vector3(0f, -1f, 0.4f), Angle = 130f, Inner = 90f, Intensity = 38f, Range = 13f, Color = new Color(1f, 0.97f, 0.94f) },
                new GfxMapLights.Fixture { Layer = "general", Note = "Gate tunnels: one soft point at the far end of each tunnel, at (±12, 3.5, 29.4) = passage top + offset. It sits 2 m behind the J_Leaf door, out of its way however it opens, 2.4 m from the side walls and 0.6 m inside the gallery mouth. When the gate opens, the passage reads lit toward the rear gallery and there is no dark mouth. E about 0.6 on the floor 3.5 m below (W(0.5) 0.88): I = 0.6*12.25/(0.88*0.98) = 8.5, set to 7 because the narrow walls bounce it back.", Type = LightType.Point, Each = "Gate passage", Anchor = "top", Offset = new Vector3(0f, 3.5f, 2.4f), Max = 2, Intensity = 7f, Range = 7f, Color = new Color(1f, 0.98f, 0.95f) },
                new GfxMapLights.Fixture { Layer = "general", Note = "Rear gallery (z 30-36, open to at least 13 m): the gallery's even daylight. Five downward wide spots on its centre line at 6 m height, 9 m apart. Floor and lower walls are even (about 0.6-1.0), with no hot bands on walls 3 m away, unlike point lights. The end walls are 4 m from the last spot. E about 0.55 on the floor 6 m below (W(0.6) 0.76): I = 0.55*36/(0.76*0.98) = 27.", Type = LightType.Spot, At = new Vector3(-18f, 6f, 33f), To = new Vector3(18f, 6f, 33f), Count = 5, Aim = new Vector3(0f, -1f, 0f), Angle = 150f, Inner = 110f, Intensity = 27f, Range = 10f, Color = new Color(1f, 0.98f, 0.95f) },
                new GfxMapLights.Fixture { Layer = "accent", Note = "The way out: the exit door at (0,0,36) as the gallery's brightest framed plane, about 2.3 against a field of 0.6-1.0. One spot from above the gallery's front wall (1.2 m clear), narrow enough to stay on the door and its frame. E +0.85 on the door at 5.7 m (cos 0.85, W(0.57) 0.81): I = 0.85*32/(0.85*0.81*0.98) = 40.", Type = LightType.Spot, At = new Vector3(0f, 5f, 31.2f), Aim = new Vector3(0f, -3f, 4.8f), Angle = 50f, Inner = 30f, Intensity = 40f, Range = 10f, Color = new Color(1f, 0.98f, 0.95f) },
            },
